    review: { reviewer: { ...s.review.reviewer, name: "Synthetic Gate Reviewer Two" } },
  }));
  await ok("runs", "resume", started.id);
  const done = await waitFor(started.id, (s) => !["running", "queued", "waiting_for_review"].includes(s));
