// Which themes become requirements: code decides, by rank and weight, never silently.
const ranked = themes
  .map((t) => ({
    theme: t,
    rank: Math.min(...t.support.map((s) => s.rank)),
    weight: weightOf(t),
  }))
  .sort((a, b) => a.rank - b.rank || b.weight - a.weight);
