let built: Built[] = [];
if (selected.length) {
  ctx.progress(0.6, "Architect is writing, critic is reviewing");
  let done = 0;
  const settled = await mapPool(
    selected,
    Math.min(archW.info.maxParallel, criticW.info.maxParallel),
    async ({ theme }): Promise<Built | null> => {
      const base = {
        theme: { label: theme.label, need: theme.need, category: theme.category },
        ...themeEvidence(theme),
        context: contextPayload,
        otherThemes: otherThemes.filter((l) => l !== theme.label).slice(0, 40),
      };
      let first;
      try {
        first = await ask(archW, archMeter, {
          system: architectSystem(setup),
          payload: { contract: CONTRACT.architect, ...base },
          schema: DraftAnswer,
          tier: "default",
          maxTokens: 3000,
        });
      } catch (err) {
        if (ctx.signal.aborted) throw err;
        const msg = errorText(err);
        const isTargetError = /targets/i.test(msg) || /at least 1/i.test(msg);
        if (isTargetError) {
          log(`"${theme.label}": held back, no measurable target.`);
          heldBack.push({
            theme: theme.label,
            reason: "No measurable target.",
            signals: theme.support.length,
          });
          return null;
        }
        if (err instanceof z.ZodError || /ZodError|schema|not valid JSON|validation/i.test(msg)) {
          log(`"${theme.label}": held back, schema-invalid draft.`);
          heldBack.push({
            theme: theme.label,
            reason: `Schema-invalid draft: ${oneLine(msg, 200)}`,
            signals: theme.support.length,
          });
          return null;
        }
        throw err;
      }
      let draft = cleanDraft(first.object, theme, briefs);
      if (draft.targets.length === 0) {
        log(`"${theme.label}": held back, no measurable target.`);
        heldBack.push({
          theme: theme.label,
          reason: "No measurable target.",
          signals: theme.support.length,
        });
        return null;
      }
      let thinking = first.thinking;
      let architectModel = first.model;
      const review1Res = await ask(criticW, criticMeter, {
        system: criticSystem(setup),
        payload: { contract: CONTRACT.critic, ...base, draft },
        schema: ReviewAnswer,
        tier: "default",
        maxTokens: 3000,
      });
      const review1 = review1Res.object;
      let review = review1;
      let criticModel = review1Res.model;
      let outcome: CritiqueOutcome = "accepted";
      let openIssues: string[] = [];
      if (review1.verdict === "reject") {
        rejected.push(
          `${theme.label}: ${oneLine(review1.rejectReason || review1.issues.join("; "), 200)}`,
        );
        return null;
      }
      if (review1.verdict === "revise") {
        let second;
        try {
          second = await ask(archW, archMeter, {
            system: architectSystem(setup),
            payload: {
              contract: CONTRACT.revise,
              ...base,
              draft,
              review: { issues: review1.issues, fixes: review1.fixes },
            },
            schema: DraftAnswer,
            tier: "default",
            maxTokens: 3000,
          });
        } catch (err) {
          if (ctx.signal.aborted) throw err;
          const msg = errorText(err);
          const isTargetError = /targets/i.test(msg) || /at least 1/i.test(msg);
          if (isTargetError) {
            log(`"${theme.label}": held back, no measurable target.`);
            heldBack.push({
              theme: theme.label,
              reason: "No measurable target.",
              signals: theme.support.length,
            });
            return null;
          }
          if (
            err instanceof z.ZodError ||
            /ZodError|schema|not valid JSON|validation/i.test(msg)
          ) {
            log(`"${theme.label}": held back, schema-invalid draft.`);
            heldBack.push({
              theme: theme.label,
              reason: `Schema-invalid draft: ${oneLine(msg, 200)}`,
              signals: theme.support.length,
            });
            return null;
          }
          throw err;
        }
        draft = cleanDraft(second.object, theme, briefs);
        if (draft.targets.length === 0) {
          log(`"${theme.label}": held back, no measurable target.`);
          heldBack.push({
            theme: theme.label,
            reason: "No measurable target.",
            signals: theme.support.length,
          });
          return null;
        }
        thinking = second.thinking ?? thinking;
        architectModel = second.model;
        const review2Res = await ask(criticW, criticMeter, {
          system: criticSystem(setup),
          payload: { contract: CONTRACT.critic, ...base, draft },
          schema: ReviewAnswer,
          tier: "default",
          maxTokens: 3000,
        });
        const review2 = review2Res.object;
        if (review2.verdict === "reject") {
          rejected.push(
            `${theme.label}: ${oneLine(review2.rejectReason || review2.issues.join("; "), 200)}`,
          );
          return null;
        }
        review = review2;
        criticModel = review2Res.model;
        outcome = review2.verdict === "accept" ? "revised" : "flagged";
        openIssues =
          review2.verdict === "accept" ? [] : review2.issues.map((x) => oneLine(x, 300));
      }
      done++;
      ctx.progress(
        0.6 + 0.28 * (done / selected.length),
        `Requirements drafted: ${done}/${selected.length}`,
      );
      return {
        theme,
        draft,
        review,
        outcome,
        firstIssues: review1.issues.map((x) => oneLine(x, 300)),
        openIssues,
        thinking,
        architectModel,
        criticModel,
      };
    },
    ctx.signal,
  );

