/** Builds the score via scoreItem (Settings weights and thresholds). */
export function scoreFromReview(
  factors: ReviewAnswer["factors"],
  scoring: Settings["scoring"],
  now: string,
  evidence: ScoringEvidence = { findings: [], records: [], sources: [] },
  evidenceLevel?: EvidenceLevel,
): ScoreBreakdown {
  const judged = {
    brand_fit: {
      value: factors.brand_fit?.value ?? 2.5,
      note: oneLine(factors.brand_fit?.note ?? "") || "Assumption: no note given.",
      by: "critic",
    },
    ease: {
      value: factors.ease?.value ?? 2.5,
      note: oneLine(factors.ease?.note ?? "") || "Assumption: no note given.",
      by: "critic",
    },
  };
  return scoreItem({
    evidence,
    judged,
    evidenceLevel,
    scoring,
    now,
  });
}
