const DIR = "/Users/johannesnirschl/Documents/temporary/EHL/data/raw/";
async function run(name: string, dataset: string, sheet: string, extra: Record<string, unknown> = {}) {
  const bytes = new Uint8Array(readFileSync(DIR + name));
  const file = { id: "file_probe", name, mimeType: "", bytes };
  const logs: string[] = [];
  const ctx = { runId: "run_probe0001", blockId: "raw-1", scope: DEFAULT_SETTINGS.defaultScope,
