  if (run?.status !== "waiting_for_review") return null;
  return (
    [...walkBlocks(run.graph)].find(
      ({ block }) =>
        block.kind === "hil" &&
        run.blockRuns.some((br) => br.blockId === block.id && br.status === "waiting_for_review"),
    ) ?? null
  );
