    reset() {
      if (get().busy || active(get().run)) return false;
      set({ workflowId: null, run: null, error: null });
      return true;
    },
    async start(graph, scope, name = "Data Flow") {
      if (get().busy || active(get().run)) return;
      set({ busy: true, error: null });
      try {
        if (!graph.blocks.length)
